mapper.select:
select pro.P_Name as pName, pro.P_Code as pCode, pro.P_Approve_Budget as pApproveBudget, sec.Sec_Name as secName, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Place as secPlace, sec.Sec_Remark as secRemark, sec.Sec_Organize_Form as secOrganizeForm, sec.Sec_Evaluate_Separation as secEvaluateSeparation, sec.Sec_Quali_Review as secQualiReview, sec.Sec_Bid_Time as secBidTime, sec.Sec_Loaction as secLoaction, sec.Sec_Investors_Quali as secInvestorsQuali, sec.Sec_Type as secType, sd.D_Function as dFunction, sd.D_Scope as dScope, sd.D_Executive_Standard as dExecutiveStandard, sd.D_Amount as dAmount, sd.D_Bid_Time as dBidTime, sd.D_Location as dLocation, c1.C_Name as secTendereeName, c2.C_Name as secAgencyName, c3.C_Name as esCompanyName, (select Sr_Id from Sec_Selection_Record where Es_Id=mn.id order by Sr_Create_Time desc limit 1) as srId, (select State from Sec_Selection_Record where Es_Id=mn.id order by Sr_Create_Time desc limit 1) as srState, mn.* from Sec_Expert_Select mn left join Pre_Project pro on pro.P_Id = mn.P_Id left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join SYS_Company c1 on c1.C_Id = sec.Sec_Tenderee left join SYS_Company c2 on c2.C_Id = sec.Sec_Agency left join SYS_Company c3 on c3.C_Id = mn.Es_Company left join Sec_Document sd on sd.Sec_Id = sec.Sec_Id and sd.D_State = 7
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.State=#{params.state}
and mn.Es_Business=#{params.esBusiness}
and mn.Es_Mode=#{params.esMode}
and mn.Es_Category=#{params.esCategory}
and mn.Es_Type=#{params.esType}
and INSTR(mn.Es_Contact,#{params.esContact})
and INSTR(mn.Es_Tel,#{params.esTel})
and likeCname(#{params.esCompanyName},c3.C_Id)=true
and INSTR(c3.C_Name,#{params.esCompanyName})
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(sec.Sec_Name,#{params.secName})
and INSTR(mn.Create_Uname,#{params.createUname})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC
